//! 🧬️ A native editor command transfers its sole mutation into one funded durable emission row.
use super::*;
use semio_framework_plugin::retained_command::{ArtifactCommandWork,ArtifactCommandInputs,ArtifactCommandWorkStep};
use semio_framework_job::{StepContext,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::RetainedCloneClose};
use std::{mem::{size_of,ManuallyDrop}};
type App=EditorApp<EnergyModelEditor>;
type Output=Emit<EnergyModelMutation,EnergyModelConfigMutation,NoDraftMutation>;
pub(super)struct EnergyModelCommandWork{bounded:BoundedArtifactCommandWork<App>,mutation:ManuallyDrop<Option<EnergyModelMutation>>,rows:ManuallyDrop<Option<Vec<EnergyModelMutation>>>,retirement:RetainedCloneClose,body:usize,native:bool,consumed:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original Energy mutation command ownership changed")}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl EnergyModelCommandWork{pub(super)fn new(tool:&'static str)->Self{Self{bounded:BoundedArtifactCommandWork::new(tool,energy_model_reduce,energy_model_extent),mutation:ManuallyDrop::new(None),rows:ManuallyDrop::new(None),retirement:Default::default(),body:0,native:false,consumed:false}}fn close_quote(&self)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.mutation.is_some(){return self.retirement.next_owner_demands::<EnergyModelMutation>(true,&None,self.body)}if self.rows.is_some(){return self.retirement.next_owner_demands::<Vec<EnergyModelMutation>>(true,&None,self.body)}Ok(Default::default())}}
impl ArtifactCommandWork<App> for EnergyModelCommandWork{
 fn tool_id(&self)->&'static str{self.bounded.tool_id}
 fn receive_original_command(&mut self,command:&mut EnergyModelEditorCommand,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let EnergyModelEditorCommand::ApplyNativeMutation{mutation,..}=command else{return Ok(true)};if self.native||self.mutation.is_some()||mutation.is_none(){return Err(invalid().into())}let d=RetirementDemand{copy_bytes:2*size_of::<Option<EnergyModelMutation>>()+size_of::<(bool,usize)>(),depth:1,..Default::default()};let body=cx.retained_grant().maximum_copy_bytes;let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{*self.mutation=mutation.take();self.body=body;self.native=true;Ok(((),receipt(d)))})?;Ok(done.is_some())}
 fn extent(&self,command:&EnergyModelEditorCommand,snapshot:&EnergyModelSnapshot,interaction:&protocol::InteractionState,context:Option<&semio_framework_plugin::app::ArtifactOwnedToolJobContext<App>>)->Option<usize>{self.bounded.extent(command,snapshot,interaction,context)}
 fn work_demands(&self,input:&ArtifactCommandInputs<'_,App>,body:usize)->Result<RetirementDemand,ValueError>{if !self.native{return self.bounded.work_demands(input,body)}if self.consumed{return Err(invalid())}if self.rows.is_none(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Vec<EnergyModelMutation>>>(),capacity_bytes:size_of::<EnergyModelMutation>(),depth:1,..Default::default()})}else{Ok(RetirementDemand{copy_bytes:size_of::<EnergyModelMutation>()+size_of::<Option<Vec<EnergyModelMutation>>>()+size_of::<Output>()+size_of::<bool>(),depth:1,..Default::default()})}}
 fn step(&mut self,input:&ArtifactCommandInputs<'_,App>,cx:&mut StepContext<'_>)->Result<ArtifactCommandWorkStep<App>,OriginalTurnFailure>{if !self.native{return self.bounded.step(input,cx)}let d=self.work_demands(input,self.body)?;if self.rows.is_none(){admit_original_construction(cx,&mut self.rows,construction(d),|_|{let mut rows=Vec::new();rows.try_reserve_exact(1).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original Energy command row could not be reserved"))?;let mut p=receipt(d);p.retained_capacity_bytes=rows.capacity()*size_of::<EnergyModelMutation>();Ok((rows,p))})?;return Ok(ArtifactCommandWorkStep::Pending{stage:"energy-original-command-row",preview:&[]})}let mut output=None;admit_original_construction(cx,&mut output,construction(d),|_|{let mut rows=self.rows.take().ok_or_else(invalid)?;rows.push(self.mutation.take().ok_or_else(invalid)?);self.consumed=true;Ok((Output::mutations(rows),receipt(d)))})?;Ok(match output{Some(output)=>ArtifactCommandWorkStep::Complete(output),None=>ArtifactCommandWorkStep::Pending{stage:"energy-original-command-handoff",preview:&[]}})}
 fn terminal_frame_release_bytes(&self)->Option<usize>{Some(size_of::<Self>())}
 fn reports_progress(&self)->bool{false}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_quote()?.copy_bytes)}
 fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(self.close_quote()?.capacity_bytes)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_quote()?.release_bytes)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(self.close_quote()?.depth)}
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<semio_framework_job::InteractiveJobCloseStep,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(semio_framework_job::InteractiveJobCloseStep::Complete{progress:Default::default()})}let d=self.close_quote()?;let mut progress=RetainedCloneProgress::default();close_original_retained_step(cx,d,|g|{let step=if !self.retirement.is_empty(){self.retirement.select(self.body)?.step(g)?}else if self.mutation.is_some(){self.retirement.begin_granted(&mut self.mutation,g)?.ok_or_else(invalid)?}else if self.rows.is_some(){self.retirement.begin_granted(&mut self.rows,g)?.ok_or_else(invalid)?}else{RetainedCloneStep::Complete(Default::default())};progress=step.progress();Ok(step)})?;Ok(if self.terminal_is_empty(){semio_framework_job::InteractiveJobCloseStep::Complete{progress}}else{semio_framework_job::InteractiveJobCloseStep::Pending{progress}})}
 fn terminal_is_empty(&self)->bool{self.mutation.is_none()&&self.rows.is_none()&&self.retirement.is_empty()}
}
impl Drop for EnergyModelCommandWork{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original Energy command work requires funded closure")}}
